+                    + ",    \"url.path\": \""
+                    + randomString(1024)
+                    + "\",    \"http.response.status_code\": "
+                    + randomFrom(200, 204, 300, 404, 500)
+                    + ",    \"http.response.bytes\": "
+                    + random.nextInt(1024)
+                    + ",    \"http.response.mime_type\": \""
