+        this.resourcesDir = resourcesDirs;
+    }
+
+    @InputFiles
+    @SkipWhenEmpty
+    @PathSensitive(PathSensitivity.RELATIVE)
+    public SetProperty<File> getSrcDirs() {
+        return srcDirs;
+    }
+
+    @Classpath
+    @InputFiles
+    public FileCollection getClasspath() {
+        return classpath;
+    }
+
+    public void setClasspath(FileCollection classpath) {
